# noVNC web interface for the Windows 3.11 VM.
# nginx (port 80) serves the noVNC client and proxies the WebSocket to
# websockify (127.0.0.1:6080), which bridges to the QEMU VNC server on 5901.
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    root /usr/share/novnc;
    index vnc.html;

    location = / {
        return 302 /vnc.html?host=$host&port=$server_port&path=websockify&autoconnect=true&resize=scale;
    }

    location /websockify {
        proxy_pass http://127.0.0.1:6080/;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
        proxy_buffering off;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}

