def is_desktop(w, h, data):
    """Program Manager up: the 1024x768 Windows desktop with its icons.

    The boot logo is 640x480 and the startup dialogs paint only about five
    distinct colours, while Program Manager's group icons paint far more.
    """
    if (w, h) != (1024, 768):
        return False
    colors = {data[i:i + 3] for i in range(0, min(len(data), 3 * w * h), 3)}
    return len(colors) >= 15

